$dir=sys_get_temp_dir().'/cw-ai-ops-'.bin2hex(random_bytes(8));mkdir($dir,0700);putenv('WORKSPACE_DATA='.$dir);putenv('WORKSPACE_DB=sqlite');putenv('WORKSPACE_CONFIG='.$dir.'/connections.json');file_put_contents($dir.'/connections.json','{}');putenv('WORKSPACE_AUTH_POLICY=local');
