 aiDeny(fn()=>aiOpsRun($db,$dev,$p,$role,'answer.tasks',$payload,$cfg['key'],function($payload,$key,$cancel)use($db,$dev){$r=entity($db,"SELECT handle FROM ai_calls WHERE status='running' AND user_id=?",[$dev['id']]);aiOpsAction($db,$dev,'ai.cancel',$r['handle']);aiCheck($cancel(),'cancellation observed by transport');return ['usage'=>['input_tokens'=>3,'output_tokens'=>1]];},$validate),409);aiCheck((int)query($db,"SELECT COUNT(*) FROM ai_calls WHERE status='cancelled'")->fetchColumn()===1,'cancelled terminal state');
